"""Build an offline, image-first reader of sealed RGB-D study results."""
import argparse
import html
import json
from pathlib import Path


def render(study, output):
    study, output = Path(study), Path(output)
    report = json.loads((study/'confirmation/report.json').read_text())
    rows = report['rows']
    summaries = report['summary']
    esc = lambda value: html.escape(str(value), quote=True)
    def fmt(value, scale=1, suffix=''):
        return '—' if value is None else f'{value*scale:.2f}{suffix}'
    table = ''.join('<tr>'+''.join('<td>'+esc(value)+'</td>' for value in (
        f'{r["width"]} px',r['variant'].replace('_',' '),f'{r["available"]}/{r["scheduled"]}',
        fmt(r['position_p95_m'],1000,' mm'),fmt(r['yaw_p95_rad'],180/3.141592653589793,'°'),
        fmt(r['wall_p95_s'],1000,' ms')) )+'</tr>' for r in summaries)
    payload = json.dumps(rows,allow_nan=False).replace('<','\\u003c')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>From pixels to position · DVIDIA research</title><style>
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f8f7f3;color:#252b28;font:16px/1.65 system-ui,sans-serif}main{max-width:1060px;margin:auto;padding:40px 24px 72px}a{color:#355943;text-underline-offset:3px}nav,footer,.eyebrow{font-size:.8rem;color:#626c65}h1{font:normal clamp(2.7rem,7vw,5rem)/1.05 Georgia,serif;letter-spacing:-.04em;max-width:12ch;margin:35px 0 24px}h2{font:normal 1.9rem Georgia,serif}.lede{font-size:1.2rem;max-width:65ch}.note{border-left:3px solid #758975;padding:14px 20px;background:#edf0e8}.viewer{border:1px solid #d9ddd4;border-radius:12px;background:#fff;overflow:hidden;margin-top:30px}.controls{display:flex;gap:15px;flex-wrap:wrap;padding:18px;border-bottom:1px solid #e0e4dc}label{font-size:.8rem;color:#536158;display:grid;gap:4px}select{font:inherit;color:#252b28;padding:10px 30px 10px 12px;background:#f9faf6;border:1px solid #bdc8ba;border-radius:6px;min-height:44px}.scene{display:grid;grid-template-columns:1.5fr 1fr;align-items:start}.scene img{display:block;width:100%;image-rendering:pixelated;background:#eee}.reading{padding:20px;overflow-wrap:anywhere}.reading h3{margin:0 0 14px;font-size:1.05rem}dl{margin:0}dt{font-size:.75rem;color:#66726a;margin-top:12px}dd{margin:2px 0}table{width:100%;border-collapse:collapse;font-size:.88rem}th,td{padding:13px 10px;text-align:left;border-bottom:1px solid #dadfd5}th{font-size:.75rem;color:#5b675e}.scroll{overflow:auto}footer{margin-top:44px}button{font:inherit;min-height:44px;padding:8px 14px;background:#f6f8f1;border:1px solid #bdc8ba;border-radius:6px;color:#314c37;cursor:pointer}@media(max-width:650px){main{padding:24px 16px 50px}.scene{grid-template-columns:1fr}.controls{gap:10px}.scene img{max-height:360px;object-fit:contain}h1{margin-top:28px}}@media(prefers-reduced-motion:no-preference){button,select{transition:background .15s}}
</style><main><nav><a href="https://research.dvidia.org/">DVIDIA research</a> / Camera-to-action research</nav><h1>From pixels to position.</h1><p class="lede">A small local estimator looks for one known block in color and depth. This experiment measures when it can estimate a pose—and when it should say it cannot.</p><p class="note">Static rendered fixtures. One orange, upright, 40 mm cube. No new learned manipulation, task success, or hardware qualification. “Available” means the estimator returned a pose; it does not mean that pose is correct.</p><section class="viewer" aria-label="Explore confirmation fixtures"><div class="controls"><label>Pose group<select id="group"></select></label><label>Resolution<select id="width"><option value="160">160 × 120</option><option value="320">320 × 240</option></select></label><label>Condition<select id="variant"></select></label></div><div class="scene"><img id="frame" alt="Rendered PiPER workstation fixture"><div class="reading" aria-live="polite"><h3 id="status"></h3><dl id="facts"></dl></div></div></section><h2>All confirmation conditions</h2><p>Each row contains 16 held-out pose groups. Variants and resolutions from one group are correlated; they are not extra independent examples. Error percentiles use available estimates only, so read them alongside the coverage.</p><div class="scroll"><table><thead><tr><th>Image width</th><th>Condition</th><th>Available</th><th>Position error p95</th><th>Yaw error p95</th><th>Estimator time p95</th></tr></thead><tbody>'''+table+'''</tbody></table></div><h2>What this measures</h2><p>RGB and depth come from the same paused native renderer. The estimator receives pixels, optical-Z depth, declared camera calibration and timing metadata. Native object pose enters only the offline evaluation after predictions are saved. Occlusion cards and duplicate objects are explicit render-only challenge geometry; these are perception fixtures, not physical manipulation trials.</p><p>Cube yaw is scored modulo 90°. Tilted objects are outside the estimator’s upright profile. Uncertainty values are geometric heuristics, not calibrated confidence bounds. Synthetic stale/future timestamps test the data contract; measured compute time does not establish sensor delivery latency or a real-time robot deadline. The renderer’s depth-accuracy limitation remains explicit.</p><footer><a href="confirmation/report.json">Full metrics</a> · <a href="protocol.json">Registered protocol</a> · <a href="freeze.json">Frozen implementation</a> · <a href="https://github.com/Dvidia-Inference/dvidia-training">Source</a></footer></main><script type="application/json" id="rows">'''+payload+'''</script><script>
const rows=JSON.parse(document.querySelector('#rows').textContent),group=document.querySelector('#group'),width=document.querySelector('#width'),variant=document.querySelector('#variant');
for(const value of [...new Set(rows.map(r=>r.group_id))])group.add(new Option(value,value));for(const value of [...new Set(rows.map(r=>r.variant))])variant.add(new Option(value.replaceAll('_',' '),value));
const metric=(v,s,u)=>v===null||v===undefined?'Unavailable':(v*s).toFixed(2)+u;
function draw(){const r=rows.find(r=>r.group_id===group.value&&r.width===Number(width.value)&&r.variant===variant.value);document.querySelector('#frame').src='confirmation/'+encodeURIComponent(r.id)+'/rgb.png';document.querySelector('#frame').alt='Pose '+r.group_id+', '+r.variant.replaceAll('_',' ')+', '+r.width+' pixel rendering';document.querySelector('#status').textContent=r.available?'Estimate returned':'Estimate withheld';const facts=[['Reason',r.reason||r.status],['Position error',metric(r.position_error_m,1000,' mm')],['Yaw error (modulo 90°)',metric(r.yaw_error_rad,180/Math.PI,'°')],['Measured estimator computation',metric(r.wall_seconds,1000,' ms')],['Scope','Simulation · known cube']];const list=document.querySelector('#facts');list.replaceChildren();for(const [key,value] of facts){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=value;list.append(dt,dd)}}for(const el of [group,width,variant])el.addEventListener('change',draw);draw();
</script></html>'''
    with output.open('x') as stream:stream.write(page)


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('study',type=Path);parser.add_argument('--output',type=Path)
    args=parser.parse_args();render(args.study,args.output or args.study/'index.html')
